async function startSync(){
  if(!mcp||syncBusy)return;syncBusy=true;syncMsg="";render();
  try{await mcp.callTool("Claude Code Remote","fire_trigger",{trigger_id:SYNC_TASK});syncMsg="Sync started. It reads the file the game wrote at your last /reload or logout, so type /reload first for fresh data. Your PC must be on with the Claude desktop app open. New data appears here by itself within a few minutes."}
  catch(e){const c=e&&e.code;syncMsg=c==="server_not_connected"?"The Claude Code Remote connector is not available in this view. Ask Claude in chat to refresh.":c==="needs_reauth"?"Reconnect Claude Code Remote in claude.ai, then try again.":(c==="approval_required"||c==="cancelled")?"Not approved, nothing was started.":(c==="blocked_by_policy"||c==="not_in_manifest")?"Starting the sync is not permitted from this view. Ask Claude in chat to refresh.":c==="rate_limited"?"Too many requests, try again in a moment.":c==="tool_error"?"The sync task reported an error: "+(e.message||"unknown"):"Could not start the sync ("+(c||"error")+"). Ask Claude in chat."}
  syncBusy=false;render();
}

