async function importAlt(c){
  impBusy=true;impMsg="";document.activeElement&&document.activeElement.blur();render();
  const id=String((c.name||"unknown")+"-"+(c.realm||"")).replace(/[^A-Za-z0-9_-]/g,"_");
  try{await db.doc("alts/"+id).set({name:c.name||"?",realm:c.realm||"",class:c.class||"",race:c.race||"",level:c.level,zone:c.zone||"",copper:c.copper||0,date:c.date||"",online:c.online??null,splits:arr(c.splits),xpSources:c.xpSources||null,deathCount:c.deathCount??arr(c.deaths).length,ts:Date.now()});
    impMsg=`Saved ${c.name} (level ${c.level}) under Character, Other characters. The plan in this app stays on Bencepo.`;impOpen=false}
  catch(e){impMsg="Import failed: "+((e&&(e.message||e.code))||"unknown error")}
  impBusy=false;render();
}
